INSERT INTO `news` (`id`, `title`, `text`, `description`, `image`, `author`, `header_image`, `keep_header`, `not_header`, `created`, `modified`, `subtitle`, `status`) VALUES
(197, 'Premiazione SocietÃ  FISKY  2023 - Palamonti - CAI Bergamo', 'Palamonti - <a href=\"https://www.facebook.com/caibergamo?__cft__[0]=AZVWPhdvSA-FI6juGByXvDw4DfYMcbmm3_1rRv_DaYjkYEzam2VONccn8uoc-60Culnem1VfJCCDat3OFsY8vPcyqLg5I57m5xDEhAcJWaoXcjTmC4fcwN6JlyFMoKT9UORqW0GPUQhC8_c44j1XpwtE_TgtlJLvNSeINfxQ5eN6X43UK17OBoSzBxmz-ztSEMo&amp;__tn__=-]K-R\" role=\"link\" tabindex=\"0\">CAI Bergamo</a> - 2 Dicembre 2023 - Grande partecipazione in occasione della premiazione 2023 delle Societ&agrave; <a href=\"https://www.facebook.com/skyrunning2023?__cft__[0]=AZVWPhdvSA-FI6juGByXvDw4DfYMcbmm3_1rRv_DaYjkYEzam2VONccn8uoc-60Culnem1VfJCCDat3OFsY8vPcyqLg5I57m5xDEhAcJWaoXcjTmC4fcwN6JlyFMoKT9UORqW0GPUQhC8_c44j1XpwtE_TgtlJLvNSeINfxQ5eN6X43UK17OBoSzBxmz-ztSEMo&amp;__tn__=-]K-R\" role=\"link\" tabindex=\"0\">FISky - Federazione Italiana Skyrunning</a>&nbsp; dove la Federazione&nbsp; ha&nbsp; messo&nbsp; in&nbsp; palio un&nbsp; montepremi&nbsp; di&nbsp; &euro;&nbsp; 13.000,00&nbsp; per&nbsp; le&nbsp; prime&nbsp; 10&nbsp; Societ&agrave; classficate. Il regolamento&nbsp; e&nbsp; la&nbsp; classifica&nbsp; finale&nbsp; ottenuta&nbsp; dalla&nbsp; somma&nbsp; dei&nbsp; punti&nbsp; che&nbsp; gli&nbsp; atleti&nbsp; delle&nbsp; varie&nbsp; Societ&agrave;&nbsp; hanno&nbsp; accumulato&nbsp; nelle&nbsp; gare&nbsp; dei&nbsp; Circuiti&nbsp; di&nbsp; Coppa&nbsp; Italia&nbsp; sono&nbsp; riportati&nbsp; al&nbsp; link :&nbsp;<a href=\"https://www.skyrunningitalia.it/pages/Classifica-e-Montepremi-per-Societa\">https://www.skyrunningitalia.it/pages/Classifica-e-Montepremi-per-Societa</a><br />\r\nLa&nbsp; convention&nbsp; &nbsp;&egrave;&nbsp; stata&nbsp; aperta&nbsp; dal&nbsp; Presidente&nbsp; della&nbsp; FISky&nbsp; ,&nbsp; Fabio&nbsp; Meraldi&nbsp; &nbsp;che&nbsp; dopo&nbsp; i&nbsp; saluti&nbsp; di&nbsp; rito&nbsp; ha&nbsp; presentato&nbsp; &nbsp;i&nbsp; Dirigenti della Federazione&nbsp; e&nbsp; relazionato&nbsp; sull&#39;attuale&nbsp; posizione&nbsp; del&nbsp; movimento.&nbsp; A&nbsp; seguire&nbsp; Paolo&nbsp; Valoti&nbsp;&nbsp;<a href=\"https://www.facebook.com/caibergamo?__cft__[0]=AZVWPhdvSA-FI6juGByXvDw4DfYMcbmm3_1rRv_DaYjkYEzam2VONccn8uoc-60Culnem1VfJCCDat3OFsY8vPcyqLg5I57m5xDEhAcJWaoXcjTmC4fcwN6JlyFMoKT9UORqW0GPUQhC8_c44j1XpwtE_TgtlJLvNSeINfxQ5eN6X43UK17OBoSzBxmz-ztSEMo&amp;__tn__=-]K-R\" role=\"link\" tabindex=\"0\">CAI Bergamo</a>&nbsp; gi&agrave;&nbsp; Presidente&nbsp; del&nbsp; sodalizio bergamasco e&nbsp; amico&nbsp; storico&nbsp; &nbsp;del&nbsp; movimento&nbsp; skyrunning&nbsp; italiano,&nbsp; ha&nbsp; fatto&nbsp; &quot;gli&nbsp; onori&nbsp; di casa&quot; ai&nbsp; numerosi&nbsp; intervenuti&nbsp; prima&nbsp; di&nbsp; cedere&nbsp; la&nbsp; parola&nbsp; al&nbsp; Dr.&nbsp; Paolo Franco,&nbsp; Assessore&nbsp; della&nbsp; Regione&nbsp; Lombardia. Le&nbsp; sue&nbsp; parole &quot;Questa mattina &egrave; stato un&nbsp; vero&nbsp; onore poter&nbsp; rappresentare la&nbsp; Regione Lombardia nella&nbsp; premiazione degli&nbsp; atleti che hanno&nbsp; partecipato ai&nbsp; Circuiti&nbsp; di&nbsp; Coppa&nbsp; Italia&nbsp; della FISky-Federazione Italiana Skyrunning . Risultati&nbsp; importanti riconosciuti&nbsp; dal&nbsp; CONI. Gli&nbsp; atleti che&nbsp; corrono&nbsp; in&nbsp; montagna rappresentano valori sani, quali&nbsp; la&nbsp; fatica&nbsp; e&nbsp; l&#39;umilt&agrave;. Essere&nbsp; qua, questa mattina,&nbsp; ribadisce l&#39;importanza dello&nbsp; sport e del sostegno alle&nbsp; discipline sportive&nbsp; che per&nbsp; la&nbsp; Regione&nbsp; Lombardia,&nbsp; rappresentano,&nbsp; da&nbsp; sempre, un&#39;autentica&nbsp; priorit&agrave;. Sostenere&nbsp; lo&nbsp; sport in&nbsp; ogni&nbsp; sua&nbsp; forma, significa sostenere pratiche di&nbsp; vita sane&nbsp; e&nbsp; salutari &quot;.&nbsp;<br />\r\nA&nbsp; seguire&nbsp; il&nbsp; Dr.&nbsp; Giulio&nbsp; Sergio Roi,&nbsp; Past President&nbsp; FISKy&nbsp; &nbsp;ha&nbsp; illustrato&nbsp; un&nbsp; importante&nbsp; report&nbsp; statistico&nbsp; sull&#39;attivata&nbsp; della&nbsp; FISKY ,&nbsp; illustrando&nbsp; nei&nbsp; minimi&nbsp; dettagli&nbsp; la&nbsp; ricerca&nbsp; condotta&nbsp; nel&nbsp; settore&nbsp; dello&nbsp; skyrunning&nbsp; in&nbsp; italia&nbsp; negli&nbsp; anni&nbsp; 2022&nbsp; e&nbsp; 2023.&nbsp; Una&nbsp; serie&nbsp; di&nbsp; dati,&nbsp; decisamente&nbsp; unici&nbsp; &nbsp;nel&nbsp; panorama&nbsp; dell&#39;outdoor&nbsp; a&nbsp; livello&nbsp; nazionale.<br />\r\nIl&nbsp; Vicepresidente&nbsp; e&nbsp; CT&nbsp; della&nbsp; Nazionale,&nbsp; Roberto&nbsp; Mattioli,&nbsp; ha&nbsp; poi&nbsp; presentato&nbsp; gli&nbsp; atleti&nbsp; delle&nbsp; Squadre&nbsp; Nazionali&nbsp; U23,&nbsp; Vicecampioni&nbsp; del&nbsp; Mondo Youth&nbsp; U23&nbsp; e della&nbsp; Squadra&nbsp; Senior,&nbsp; Campione&nbsp; del&nbsp; Monde&nbsp; in&nbsp; carica Skysnow,&nbsp; Campione&nbsp; del&nbsp; Mondo&nbsp; in&nbsp; Carica Skyrunning e&nbsp; Vicecampioni&nbsp; D&#39;Europa&nbsp; 2023,&nbsp; che&nbsp; il&nbsp; prossimo&nbsp; anno&nbsp; difenderanno&nbsp; &nbsp;i&nbsp; titoli&nbsp; conquistati&nbsp; in&nbsp; Montenegro con&nbsp; gli&nbsp; U23&nbsp; e&nbsp; in&nbsp; Spagna&nbsp; con&nbsp; la&nbsp; Squadra&nbsp; Senior.&nbsp; &nbsp;<br />\r\nIl Vicepresidente&nbsp; ha&nbsp; poi&nbsp; presentato&nbsp; il&nbsp; calendario&nbsp; agonistico&nbsp; 2024 , dove&nbsp; sono&nbsp; gi&agrave;&nbsp; presenti&nbsp; oltre&nbsp; 75&nbsp; gare&nbsp; e&nbsp; alcune&nbsp; altre&nbsp; si&nbsp; aggiungeranno&nbsp; a&nbsp; breve.&nbsp; Fra&nbsp; queste&nbsp; le&nbsp; gare&nbsp; che&nbsp; assegneranno&nbsp; i&nbsp; titoli&nbsp; Italiani&nbsp; nelle&nbsp; varie&nbsp; specialit&agrave;&nbsp; skyrunning,&nbsp; i&nbsp; Circuti&nbsp; di&nbsp; Coppa&nbsp; Italia dove&nbsp; la&nbsp; Federazione&nbsp; ha&nbsp; confermato&nbsp; di&nbsp; investire&nbsp; 10.000,00&nbsp; euro&nbsp; in&nbsp; montepremi,&nbsp; il&nbsp; Circutio&nbsp; di&nbsp; Coppa&nbsp; Italia&nbsp; Giovani&nbsp; dove&nbsp; FISky&nbsp; in&nbsp; collaborazione&nbsp; con&nbsp; i&nbsp; vari&nbsp; organizzatori&nbsp; st&agrave;&nbsp; lavorando con&nbsp; particolare&nbsp; dedizione&nbsp; per&nbsp; la&nbsp; crescita&nbsp; del&nbsp; movimento&nbsp; giovanile ed&nbsp; il&nbsp; ritorno&nbsp; del circuito&nbsp; &nbsp;SNS- Skyrunner&nbsp; Nationale Series.&nbsp;<br />\r\nOltre&nbsp; alle&nbsp; prime&nbsp; 10&nbsp; Societ&agrave;&nbsp; classificate,&nbsp; menzione&nbsp; e&nbsp; premio&nbsp; speciale&nbsp; per&nbsp; la&nbsp; A.S.D.&nbsp;<a href=\"https://www.facebook.com/Gaaren.Beahero/?locale=it_IT\"> Team GAAREN#BEaHERO&nbsp;</a> di&nbsp; Bergamo,&nbsp; che&nbsp; con&nbsp; i&nbsp; suoi&nbsp; 209&nbsp; tesserati&nbsp; &nbsp;svolge&nbsp; un&#39;importante&nbsp; funzione&nbsp; culturale e&nbsp; di&nbsp; promozione&nbsp; per&nbsp; la&nbsp; disciplina&nbsp; alpinista&nbsp; dello&nbsp; skyrunning.<br />\r\nLa&nbsp; convention&nbsp; si&nbsp; &egrave;&nbsp; conclusa&nbsp; con&nbsp; l&#39;aperitivo&nbsp; al&nbsp;<a href=\"https://www.caibergamo.it/sezione-bergamo-antonio-locatelli/ristorante-rifugio-citta\"> &quot;Rifugio&nbsp; in&nbsp; Citt&agrave;&quot;&nbsp;</a>&nbsp; ,&nbsp; il&nbsp; ristorante&nbsp; interno&nbsp; alla&nbsp; sede&nbsp; del&nbsp; CAI&nbsp; Bergamo.<br />\r\n<br />\r\n<br />\r\n<br />\r\n<br />\r\n<br />\r\n<br />\r\n<br />\r\n<br />\r\n<br />\r\n<br />\r\n<br />\r\n&nbsp;', 'Presentati  i  calendari 2024 e la Nazionale Italiana Skyrunning', 'https://www.skyrunningitalia.it/files/images/FISKY_PALAMONTI_CAI.jpg', '', NULL, 0, 0, '2023-12-03 21:23:47', '2023-12-03 21:35:26', NULL, 1),
(198, 'Daniele Cappelletti Ã¨ il  primo Allenatore  di  IV LIVELLO  Skyrunning', 'Questo fine&nbsp; d&#39;anno&nbsp; &egrave; foriero&nbsp; di&nbsp; grandi&nbsp; soddisfazioni&nbsp; per&nbsp; la&nbsp; <a href=\"https://www.skyrunningitalia.it/\">@fisky</a><br />\r\nDopo il&nbsp; successo&nbsp; della&nbsp; convention&nbsp; al&nbsp; <a href=\"https://www.caibergamo.it/\">Palamonti - CAI&nbsp; Bergamo</a>&nbsp; del&nbsp; 2&nbsp; Dicembre,&nbsp; un&#39;altra&nbsp; importante&nbsp; notizia:&nbsp; Daniele Cappelletti ,&nbsp; gi&agrave; atleta&nbsp; Mondial - medagliato&nbsp; della&nbsp; Nazionale&nbsp; Italiana&nbsp; Skyrunning ,&nbsp; detentore&nbsp; del&nbsp; &nbsp;Record D+ 24H ,&nbsp; Consigliere&nbsp; Nazionale FISKY in&nbsp; Rappresentanza&nbsp; degli Atleti,&nbsp; oggi&nbsp; ha&nbsp; conseguito&nbsp; la&nbsp; qualifica&nbsp; di&nbsp; Allenatore&nbsp; di&nbsp; IV&nbsp; Livello&nbsp; Europeo&nbsp; &nbsp;presso&nbsp; la&nbsp; Scuola&nbsp; dello&nbsp; Sport&nbsp; - SPORT E SALUTE - Centro&nbsp; di&nbsp; Preparazione&nbsp; Olimpica&nbsp; &quot;Giulio Onesti&quot;&nbsp; &nbsp;a&nbsp; Roma .&nbsp;&nbsp;<br />\r\n<br />\r\n<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/Daniele_Cappeleltti_Allenatore.jpg\" style=\"width: 820px; height: 866px;\" /><br />\r\n<br />\r\nUna grande soddisfazione,&nbsp; per <a href=\"https://www.facebook.com/hashtag/skyrunningitalia?__eep__=6&amp;__cft__[0]=AZUgNWtjwE2kCqJlyK4UStZ_sxzG29mcmFIw8z71fZtAjp9VySRicWL-lxi1JOstwGgiaDFnx7JH4x-t6s3IAx6VIkyXuQs_DsOa_pbl0jBWVn0WlcapJoQJvo2H7uz8tsDHbm_95jKCP3f4qp_kuXGYcNaHH6WT4sTQqDfN-42tYIVGTClidKHc4rG9RT8HZ2JwedgYcJreOnlBw6h_yGkF&amp;__tn__=*NK-R\" role=\"link\" tabindex=\"0\">#skyrunningitalia</a> <a href=\"https://www.facebook.com/hashtag/fisky?__eep__=6&amp;__cft__[0]=AZUgNWtjwE2kCqJlyK4UStZ_sxzG29mcmFIw8z71fZtAjp9VySRicWL-lxi1JOstwGgiaDFnx7JH4x-t6s3IAx6VIkyXuQs_DsOa_pbl0jBWVn0WlcapJoQJvo2H7uz8tsDHbm_95jKCP3f4qp_kuXGYcNaHH6WT4sTQqDfN-42tYIVGTClidKHc4rG9RT8HZ2JwedgYcJreOnlBw6h_yGkF&amp;__tn__=*NK-R\" role=\"link\" tabindex=\"0\">#fisky</a> <a href=\"https://www.facebook.com/skyrunning2023?__cft__[0]=AZUgNWtjwE2kCqJlyK4UStZ_sxzG29mcmFIw8z71fZtAjp9VySRicWL-lxi1JOstwGgiaDFnx7JH4x-t6s3IAx6VIkyXuQs_DsOa_pbl0jBWVn0WlcapJoQJvo2H7uz8tsDHbm_95jKCP3f4qp_kuXGYcNaHH6WT4sTQqDfN-42tYIVGTClidKHc4rG9RT8HZ2JwedgYcJreOnlBw6h_yGkF&amp;__tn__=-]K-R\" role=\"link\" tabindex=\"0\">FISky - Federazione Italiana Skyrunning</a>&nbsp; che&nbsp; desideriamo&nbsp; condividere&nbsp; con&nbsp; tutti&nbsp; voi, per questo traguardo di Daniele Cappelletti primo tecnico in Italia di IV LIVELLO nella disciplina alpinistica Skyrunning e primo tecnico in Italia nello Sci Alpinismo. Il lavoro, la seriet&agrave;, la costanza e l&#39;onest&agrave; intellettuale alla fine emergono sempre.<br />\r\n<br />\r\n<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/diploma_Daniele_Cappelletti.JPG\" style=\"width: 497px; height: 706px;\" />\r\n<h2><strong>but.... stay tuned&nbsp;<br />\r\nother great news coming soon</strong></h2>\r\n', 'but...stay tuned other great news coming soon', 'https://www.skyrunningitalia.it/files/images/CAPPELELTTI_DANIELE_Allenatore_IV_livello.jpg', '', NULL, 0, 0, '2023-12-14 23:53:07', '2023-12-14 23:54:00', NULL, 1),
(199, 'SKYRUNNING ITALIA  -  Atleti Interesse Nazionale 2024', '<br />\r\nLa <a href=\"https://www.facebook.com/skyrunning2023?__cft__[0]=AZUTpeVSbvHrjHsV1roHxZdwFJO7TwzhxSd_67Of9-sYTh6YUBae0jiOgI-4r1lqLmbuUatrkFinEFNRl29UnS7o0RDeaeyDaHYp3KwOgDhaMfqIl1XLLOBo-zMUmYpLa8f8MisyhvIHeldAIciUzhdMZVpoD_3tPiaS45Nfhp46za0xWwdNHHZiUAetNoY0W8A&amp;__tn__=-]K-R\" role=\"link\" tabindex=\"0\">FISky - Federazione Italiana Skyrunning</a> ufficializza la lista degli &quot;Atleti di interesse Nazionale &quot; , punto di partenza per riconfermare i titoli Mondiali Skysnow, Skyrunning e il podio dei Mondiali Youth<br />\r\n<a href=\"https://www.facebook.com/skyrunning2023?__cft__[0]=AZUTpeVSbvHrjHsV1roHxZdwFJO7TwzhxSd_67Of9-sYTh6YUBae0jiOgI-4r1lqLmbuUatrkFinEFNRl29UnS7o0RDeaeyDaHYp3KwOgDhaMfqIl1XLLOBo-zMUmYpLa8f8MisyhvIHeldAIciUzhdMZVpoD_3tPiaS45Nfhp46za0xWwdNHHZiUAetNoY0W8A&amp;__tn__=-]K-R\" role=\"link\" tabindex=\"0\">FISky - Federazione Italiana Skyrunning</a><br />\r\n<a href=\"https://www.facebook.com/crazymountainwear?__cft__[0]=AZUTpeVSbvHrjHsV1roHxZdwFJO7TwzhxSd_67Of9-sYTh6YUBae0jiOgI-4r1lqLmbuUatrkFinEFNRl29UnS7o0RDeaeyDaHYp3KwOgDhaMfqIl1XLLOBo-zMUmYpLa8f8MisyhvIHeldAIciUzhdMZVpoD_3tPiaS45Nfhp46za0xWwdNHHZiUAetNoY0W8A&amp;__tn__=-]K-R\" role=\"link\" tabindex=\"0\">Crazy - Performance Mountainwear from the Italian Alps</a><br />\r\n<a href=\"https://www.facebook.com/LoackerGeorgia?__cft__[0]=AZUTpeVSbvHrjHsV1roHxZdwFJO7TwzhxSd_67Of9-sYTh6YUBae0jiOgI-4r1lqLmbuUatrkFinEFNRl29UnS7o0RDeaeyDaHYp3KwOgDhaMfqIl1XLLOBo-zMUmYpLa8f8MisyhvIHeldAIciUzhdMZVpoD_3tPiaS45Nfhp46za0xWwdNHHZiUAetNoY0W8A&amp;__tn__=-]K-R\" role=\"link\" tabindex=\"0\">Loacker<br />\r\n<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/Atleti_interesse_nazionale_2024.jpg\" style=\"width: 641px; height: 906px;\" /></a>', 'Al  lavoro  per  riconfermarsi  Campioni  Mondiali ', 'https://www.skyrunningitalia.it/files/images/FISKY_CAMPIONE_DEL_MONDO.jpg', '', NULL, 0, 0, '2024-01-18 22:46:40', '2024-01-26 15:19:57', NULL, 1),
(200, 'Aperte le iscrizioni 2024  per  il  corso \"Istruttori Skyrunning  1Â° livello\"', '<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/2024_Corso_istruttori_di_1_locadina_template__page-0001.jpg\" style=\"width: 650px; height: 919px;\" />', '30 ore di  lezione  online e  verifica finale  in  presenza', 'https://www.skyrunningitalia.it/files/images/corso_istruttori.jpg', '', NULL, 0, 0, '2024-02-01 19:00:55', '2024-02-01 19:01:03', NULL, 1),
(201, 'Luca del Pero e Corinna Ghirardi si laureano Campioni Italiani Skysnow  Classic 2024', '<br />\r\n<img alt=\"ðŸƒ\" height=\"16\" referrerpolicy=\"origin-when-cross-origin\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t3b/1/16/1f3c3.png\" width=\"16\" />&nbsp;Al termine di una sfida serrata a ranghi ristretti, &egrave; stato l&rsquo;azzurro Luca del Pero (Ski Lario Runners ASD), Campione del Mondo SkySnow in carica, a tagliare per primo il traguardo fermando il tempo a 48&rsquo;03&rsquo;&rsquo;. Secondo Lorenzo Rota Martir, e terzo William Boffelli. Quarto posto per Gianluca Ghiano (Santiano Dante ASD): il Campione Italiano SkySnow uscente cede il titolo con l&rsquo;onore delle armi al termine di una gara condotta all&rsquo;inseguimento dei tre migliori di giornata, mantenuti a poca distanza.<br />\r\n<br />\r\n<img alt=\"ðŸƒâ€â™€\" height=\"16\" referrerpolicy=\"origin-when-cross-origin\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/ta9/1/16/1f3c3_200d_2640.png\" width=\"16\" />&nbsp;Anche in campo femminile micce accese fin dall&rsquo;avvio: Corinna Ghirardi (Skyrunning Adventure ASD) conquista il tricolore con il tempo di 1h 00&rsquo; 37&rsquo;&rsquo;, incalzata alle spalle da Benedetta Broggi (ASD Sport Project VCO) che con una prova di forza mantiene regolare il suo distacco dalla prima sia in salita che in discesa. Terza Giulia Pol (G.S. Orecchiella Garfagnana ASD), autrice di una sorprendente rimonta nel finale su Chiara Giovando (Pegarun ASD), quarta al traguardo.<br />\r\n<br />\r\n<img alt=\"ðŸ‘¥\" height=\"16\" referrerpolicy=\"origin-when-cross-origin\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t8b/1/16/1f465.png\" width=\"16\" />&nbsp;La Weissrunner Gressoney &egrave; stata prova qualificante per la selezione del Campionato Mondiale SkySnow 2024. Ottimi segnali arrivati al CT Roberto Mattioli: &ldquo;Al termine di questa seconda tappa di <a href=\"https://www.skyrunningitalia.it/pages/CRAZY-SkySnow-Italy-Cup-2024\">CRAZY SkySnow Italy Cup</a> inizia a delinearsi la rappresentativa nazionale che difender&agrave; i colori al Mondiale di Tarvisio.&rdquo;<br />\r\n<br />\r\n<a href=\"https://wedosport.net/vedi_circuito.cfm?circuito=734\">Classifiche complete&nbsp; qui </a><br />\r\nPH Stefano Jeantet', 'Assegnati i  titoli Italiani  Assoluti e di  Categoria SkySnow alla GRESSONEY WEISSRUNNER', 'https://www.skyrunningitalia.it/files/images/FISKY_Corinna_Ghirardi.jpg', '', NULL, 0, 0, '2024-02-04 21:45:15', '2024-02-04 21:49:03', NULL, 1),
(202, 'Ghiano e Ghirardi campioni di CRAZY SkySnow Italy Cup by FISky', 'Con la SkySnow Schia Monte Caio appenninica di sabato 17 febbraio si &egrave; conclusa la caccia allo scudetto tricolore di&nbsp;<strong>CRAZY SkySnow Italy Cup&nbsp;</strong>che era partita l&rsquo;ultimo fine settimana di gennaio sulle nevi di Sauze d&rsquo;Oulx ed era proseguita il primo weekend di febbraio con la Weissrunner di Gressoney.&nbsp;<strong>Il circuito federale promosso da FISky e sostenuto dal brand CRAZY&nbsp;</strong>ha visto gli specialisti azzurri della corsa sui sentieri innevati confrontarsi sulle tre prove in calendario, valevoli sia per l&rsquo;assegnazione dei titoli italiani assoluti e di categoria che per la<strong>&nbsp;selezione della rappresentativa azzurra ai Mondiali SkySnow di Tarvisio</strong>&nbsp;in programma il secondo fine settimana di marzo: venerd&igrave; 8 nella prova Vertical (Monte Lussari), sabato 9 in quella Classic di Monte Mangart Winter Trail. Iscrizioni e numeri in aumento per il circuito nel suo complesso, a testimonianza della crescita costante del movimento.<br />\r\nAl termine delle tre prove in calendario (Sauze SkySnow Race, Gressoney Weissrunner e SkySnow Schia Monte Caio) la vittoria finale del circuito CRAZY SkySnow Italy Cup 2024 &egrave; andata a&nbsp;<strong>Gianluca Ghiano (ASD Santiano Dante) e Corinna Ghirardi (ASD Skyrunning Adventure)</strong>. Entrambi atleti azzurri, il giovane atleta emergente di Pinerolo e la forte campionessa bresciana portacolori hanno dettato legge durante il breve arco temporale (tre settimane) nelle quali si &egrave; svolta la Coppa Italia.&nbsp;<strong>Due vittorie e 272 punti totalizzati per lo skyrunner piemontese</strong>&nbsp;(vincitore nella Sauze SkySnow Race e nella SkySnow Schia Monte Caio).<strong>&nbsp;Percorso netto addirittura (300 punti) per la pluricampionessa lombarda</strong>&nbsp;che alle vittorie di Sauze e Schia ha aggiunto quella di Gressoney, dove Ghiano si era dovuto accontentare del quarto posto.<br />\r\nPiazza d&rsquo;onore nella classifica finale per&nbsp;<strong>Fabio Martinat</strong>&nbsp;(ASD Piossasco Trail Runners) tra gli uomini e per&nbsp;<strong>Giulia Pol&nbsp;</strong>(ASD Orecchiella Garfagnana) nel ranking fermminile. Terzo posto per&nbsp;<strong>Matteo Lora&nbsp;</strong>(ASD Skyrunning Adventure)&nbsp;<strong>e Benedetta Broggi&nbsp;</strong>(ASD Sport Project VCO).<br />\r\nSvoltesi a Schia al termine dell&rsquo;ultima tappa del circuito, le premiazioni finale di CRAZY SkySnow Italy Cup hanno assegnato&nbsp;<strong>un montepremi federale da tremila euro&nbsp;</strong>che i titolari dei tre gradini del podio maschile e di quello femminile si sono spartiti cos&igrave;: 700 euro per il primo posto, 500 per il secondo, 300 per il terzo.<br />\r\nIn questo passaggio-chiave della stagione invernale, i numeri del movimento registrano una costante crescita,&nbsp;<strong>per la giustificata soddisfazione del presidente FISky Fabio Meraldi</strong>:\r\n<p>&ldquo;Anche quest&rsquo;anno il circuito ha visto un aumento di partecipazione testimoniato dal&nbsp;<strong>sold-out delle iscrizioni sia nella tappa di Gressoney che in quella di Schia</strong>, con un ottimo incremento anche a Sauze d&rsquo;Oulx, a testimonianza della crescita a livello esponenziale del movimento sportivo che fa riferimento alla Federazione Italiana Skyrunning&rdquo;.</p>\r\n', 'Diramata al termine dell\'ultima tappa di Coppa Italia a Schia Monte Caio la lista degli azzurri per i Mondiali SkySnow', 'https://www.skyrunningitalia.it/files/images/CRAZY_SKY_SNOW_ITALY_CUP_2024.jpg', '', NULL, 0, 0, '2024-02-21 19:06:24', '2024-02-21 19:06:31', NULL, 1),
(203, 'Mondiali Skysnow a  Tarvisio - ITALIA CAMPIONE DEL MONDO A SQUADRE', '<strong>L&rsquo;Italia &egrave; Campione del Mondo a Squadre e bissa il Mondiale di Sierra Nevada - Spagna 2022</strong><br />\r\n<br />\r\nBottino di medaglie per l&#39;Italia dello Skyrunning che <strong>conquista ben 8 medaglie delle 21 in palio</strong> ai Mondiali SkySnow a Tarvisio : <strong>3 ORI, 1 ARGENTO e 4 BRONZI&nbsp;&nbsp;</strong>\r\n<p dir=\"ltr\"><strong>Partenza col botto della Nazionale Skyrunning che nella prima prova in programma, il Vertical del Monte Lussari, si aggiudica ben tre delle sei medaglie in palio.</strong></p>\r\n\r\n<p dir=\"ltr\">SkySnow World Championship - Tarvisio (UD) - Al termine di una gara di altissimo livello resa suggestiva (ed impegnativa) dalla leggera nevicata che ha accompagnato gli atleti fin dal via, la squadra azzurra va subito a segno conquistando il titolo mondiale e un tris di medaglie frutto di una grande prestazione di squadra.</p>\r\n\r\n<p dir=\"ltr\">In cima al Monte Lussari, <strong>Tadei Pivk </strong>(Aldo Moro ASD) conquista il titolo di Campione del Mondo di specialit&agrave; fermando il crono a 36&#39; 47&#39;&#39; davanti allo spagnolo Diaz Ortega e al connazionale, e campione mondiale uscente, <strong>Luca Del Pero</strong> (Sky Lario Runners ASD) che si aggiudica il bronzo iridato.&nbsp;</p>\r\n\r\n<p dir=\"ltr\">L&rsquo;azzurro costruisce il proprio successo con un exploit sulle massime pendenze (oltre il 45%) nella seconda met&agrave; del tracciato di 3,6 km che ha condotto gli atleti dalla partenza posizionata a 815m fino ai 1790m del Santuario del Monte Lussari (974m dislivello positivo). Oro mondiale per Pivk, friulano originario di Tarvisio, impreziosito dall&#39;emozione di un risultato conquistato sulle nevi di casa.&nbsp;</p>\r\n\r\n<p dir=\"ltr\">In campo femminile, speranze di podio esaudite da <strong>Corinna Ghirardi</strong> (Skyrunning Adventure ASD) che con il tempo di 43&#39; 39&#39;&#39; agguanta una combattuta medaglia di bronzo con una gara corsa alle calcagna dell&#39;imprendibile svedese Tove Alexandersson, prima con 42&#39; 28&#39;&#39;.</p>\r\n\r\n<p dir=\"ltr\">Prova onorata da parte di tutti gli azzurri chiamati a confrontarsi con i rappresentanti di ben 27 nazioni: 5&deg; posto per <strong>Marcello</strong> <strong>Ugazio</strong> (Sport Project VCO ASD), impegnato nella corsa all&#39;inseguimento dei primi fin dalle prime battute. Per le azzurre <strong>Chiara Giovando</strong> (Pegarun ASD) e<strong> Benedetta Broggi</strong> (Sport Project VCO ASD) l&#39;esordio iridato si chiude rispettivamente in 6&deg; e 11&deg; posizione.&nbsp;</p>\r\n<strong>Nella seconda e ultima giornata di gare iridate fioccano ancora medaglie per il team Azzurro: oltre alla<br />\r\nvittoria di squadra, Luca Del Pero &egrave; argento nella distanza Classic e medaglia d&rsquo;oro nella Combinata.<br />\r\nCorinna Ghirardi si ripete conquistando di nuovo il bronzo, sia in gara Classic che nella Combinata.</strong>\r\n\r\n<p dir=\"ltr\">SkySnow World Championship - Tarvisio (UD) - Nella prova di SkySnow Classic disputata sul tracciato di 17km del Monte Mangart Winter Trai,<strong> Luca Del Pero</strong> -Campione del Mondo uscente- agguanta la medaglia d&#39;argento confermandosi assoluto protagonista sulla scena mondiale. In gara donne un&#39;inesauribile<strong> Corinna Ghirardi</strong> (Skyrunning Adventure ASD) replica il risultato ottenuto nella prova Vertical conquistando la medaglia di bronzo anche nella prova Up and Down.</p>\r\n\r\n<p dir=\"ltr\">Sullo spettacolare percorso friulano con partenza dal Lago Superiore di Fusine, uno scatenato Martin Nilsson (SWE) prende il largo nella prima met&agrave; di gara ed incrementa fino al passaggio ai 1380m del Rifugio Zacchi, seguito a distanza dall&#39;azzurro <strong>Del Pero</strong> (ASD Ski Lario Runners) che con una prova brillante limita il gap prima di tentare l&#39;ultimo forcing sulla discesa finale. Anche al femminile gara dominata dalla Svezia: Tove Alexandersson ipoteca la vittoria gi&agrave; nei primi chilometri di gara e lascia al drappello delle inseguitrici la lotta per il podio; l&rsquo;azzurra<strong> Corinna Ghirardi</strong> taglia il traguardo con il tempo di 1:24:52 riuscendo a difendere una terza posizione non scontata, davanti di pochi secondi alle avversarie in rimonta.&nbsp;</p>\r\n\r\n<p dir=\"ltr\">In campo maschile centrano la Top Ten mondiale<strong> Lorenzo Rota Martir,</strong> che si ferma ai piedi del podio con un ottimo 4&deg; posto, e <strong>Gianluca Ghiano </strong>(ASD Santiano Dante) 6&deg; al traguardo. Tra le donne chiudono fra le migliori dieci anche <strong>Benedetta Broggi </strong>(Sport Project VCO ASD) e <strong>Giulia Pol</strong> (ASD Orecchiella Garfagnana) che spuntano rispettivamente la 9&deg; e la 10&deg; posizione.</p>\r\n\r\n<p dir=\"ltr\">La selezione nazionale guidata dal <strong>CT Roberto Mattioli</strong> chiude la due giorni iridata di Tarvisio facendo bottino pieno: oltre al prestigioso <strong>titolo a Squadre</strong> e agli eccellenti risultati conseguiti nelle prove individuali Vertical e Classic, completano il successo mondiale le due medaglie ottenute dagli Azzurri nella Combinata <strong>(oro per Luca Del Pero e bronzo per Corinna Ghirardi)<br />\r\n<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/SKYSNOW_RANKING_FISKY.JPG\" style=\"width: 678px; height: 712px;\" /></strong></p>\r\n', 'Bottino di medaglie per l\'Italia dello Skyrunning che conquista ben 8 medaglie delle 21 in palio', 'https://www.skyrunningitalia.it/files/images/CRAZY_SKY_SNOW_ITALY_CUP_2024_b.jpg', '', NULL, 0, 0, '2024-03-10 17:57:57', '2024-03-10 18:10:45', NULL, 1),
(204, 'Corso Istruttori 1Â° Livello', 'Nel weekend del&nbsp; 23 e 24&nbsp; Marzo si&nbsp; &egrave;&nbsp; concluso&nbsp; &nbsp;il&nbsp; primo&nbsp; corso 2024 per&nbsp; Istruttori Skyrunning&nbsp; 1&deg; livello&nbsp; a&nbsp; Vezzano sul Crostolo (RE)&nbsp; sede&nbsp; del&nbsp; S.I.T. - Settore&nbsp; Istruzione&nbsp; Tecnica.<br />\r\n22&nbsp; nuovi&nbsp; Istruttori&nbsp; provenienti&nbsp; da&nbsp; Valle d&#39;Aosta, Piemonte, Lombardia, Veneto, Emilia, Sardegna,&nbsp; Toscana e Lazio&nbsp; hanno&nbsp; completato&nbsp; il&nbsp; corso&nbsp; di&nbsp; 30&nbsp; ore&nbsp; online&nbsp; e&nbsp; verifica&nbsp; finale&nbsp; con&nbsp; prove&nbsp; pratiche in&nbsp; presenza.<br />\r\nLe&nbsp; materie&nbsp; trattate&nbsp; e&nbsp; le&nbsp; nozioni&nbsp; acquisite&nbsp; sono&nbsp; il&nbsp; punto&nbsp; di&nbsp; partenza&nbsp; per&nbsp; poter&nbsp; apportare&nbsp; un&nbsp; importante&nbsp; contributo&nbsp; alla&nbsp; pratica&nbsp; dello&nbsp; skyrunning.<br />\r\n<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/IMG_1714.jpg\" style=\"width: 640px; height: 480px;\" /><br />\r\n&nbsp;', 'Si Ã¨  concluso presso  la  sede del  S.I.T. il  primo  corso 2024 per  Istruttori', 'https://www.skyrunningitalia.it/files/images/Verifica_1_livello_FISKY_2024.jpg', '', NULL, 0, 0, '2024-03-28 10:31:35', '2024-03-28 10:42:12', NULL, 1),
(205, 'Corso di  formazione per  Direttore di  Percorso Skyrunning', '<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/2024_locandina_Direttori_di_Percorso_page-0001.jpg\" style=\"width: 640px; height: 905px;\" />..', 'Riservato a Guide Alpine e Aspiranti Guide Alpine -  21 Maggio 2024', 'https://www.skyrunningitalia.it/files/images/Corso_FISKY_Bergamo(1).jpg', '', NULL, 0, 0, '2024-04-16 15:09:48', '2024-04-17 10:52:52', NULL, 1),
(206, 'Corso di formazione per Direttori di Gara Skyrunning', '<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/2024-Corso-direttori-di-gara.jpg\" style=\"width: 650px; height: 919px;\" />', 'Aperto a tutti  i rappresentanti delle SocietÃ  affiliate - 25 Maggio 2024', 'https://www.skyrunningitalia.it/files/images/Corso_FISKY_Bergamo(2).jpg', '', NULL, 0, 0, '2024-04-17 11:03:14', '2024-04-17 11:03:21', NULL, 1),
(207, 'Corso per Direttori di Percorso Skyrunning', 'In data&nbsp; 21 Maggio 2024&nbsp; presso il&nbsp; <a href=\"https://www.caibergamo.it/\">Palamonti , sede&nbsp; CAI a&nbsp; Bergamo&nbsp;</a>&nbsp; si &egrave; tenuto&nbsp; &nbsp;il&nbsp; 4&deg;&nbsp; Corso corso&nbsp; di&nbsp; formazione&nbsp; promosso&nbsp; da&nbsp;<a href=\"https://www.guidealpine.it/\"> CONAGAI</a>&nbsp;Collegio Nazionale Guide Alpine Italiane&nbsp; &nbsp;e&nbsp; &nbsp;<a href=\"https://www.skyrunningitalia.it/\">FISKY</a> - Federazione Italiana Skyrunning&nbsp; per&nbsp; la formazione&nbsp; di&nbsp; Direttori&nbsp; di&nbsp; Percorso&nbsp; sulle&nbsp; gare&nbsp; &quot;Skyrunning&quot;&nbsp; patrocinate ed&nbsp; inserite&nbsp; nel&nbsp; calendario&nbsp; ufficiale&nbsp; <a href=\"https://www.skyrunningitalia.it/pages/Calendario-Gare-2024\">FISKY</a>&nbsp;,come da&nbsp; protocollo d&#39;intesa tra&nbsp; i due&nbsp; soggetti&nbsp; del&nbsp; 18 Gennaio 2018.<br />\r\n<br />\r\nVenti&nbsp; i&nbsp; partecipanti&nbsp; &nbsp; che&nbsp; si&nbsp; aggiungono&nbsp; all&#39;elenco&nbsp; delle&nbsp; oltre&nbsp; 40 Guide&nbsp; Alpine (Direttori&nbsp; di&nbsp; Percorso)&nbsp; per&nbsp; fornire&nbsp; il&nbsp; massimo&nbsp; della professionalit&agrave;&nbsp; e&nbsp; &nbsp;sicurezza&nbsp; ai&nbsp; partecipanti&nbsp; degli&nbsp; eventi&nbsp; promossi&nbsp; dalla&nbsp;<a href=\"https://www.skyrunningitalia.it/\"> FISKY - Federazione Italiana Skyrunning&nbsp;</a><br />\r\n<br />\r\nUn&nbsp; particolare&nbsp; ringraziamento&nbsp; a&nbsp; tutti&nbsp; gli&nbsp; intevenuti&nbsp; e&nbsp; al&nbsp; <a href=\"https://www.caibergamo.it/\">CAI Bergamo</a>&nbsp;per&nbsp; l&#39;ospitalit&agrave;<br />\r\n<br />\r\n<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/PHOTO-2024-05-21-10-05-33.jpg\" style=\"width: 600px; height: 450px;\" /><br />\r\n&nbsp;', 'Al  Palamonti sede CAI  a  Bergamo', 'https://www.skyrunningitalia.it/files/images/Corso_FISKY_Bergamo_2024.jpg', '', NULL, 0, 0, '2024-05-24 16:03:21', '2024-05-28 15:45:09', NULL, 1),
(208, 'Lo  Skyrunning   va  a  scuola ', '<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/DANIELE_CAPPELLETTI_b.jpg\" style=\"width: 680px; height: 840px;\" /><br />\r\nIn&nbsp; occasione&nbsp; dell&#39;anniversario dei 150 anni di fondazione dell<a href=\"https://it.wikipedia.org/wiki/Istituto_agrario_di_San_Michele_all%27Adige\">&#39;Istituto Agrario di San Michele all&#39;Adige </a>&nbsp;&egrave; stato organizzato un incontro, con gli studenti e le studentesse, sul tema dello sport.<br />\r\nIn&nbsp; rappresentanza&nbsp; della&nbsp; <a href=\"https://www.skyrunningitalia.it/\">FISKY-Federazione Italiana Skyrunning</a>&nbsp; ha&nbsp; partecipato il&nbsp; <a href=\"https://scuoladellosport.sportesalute.eu/scuoladellosport/formazione-sds/corsi/corso/3847-23%C2%B0_Corso_Nazionale_per_i_Tecnici_di_IV_Livello_Europeo_-_7_moduli_(percorsi_giovanile_ed_%C3%A9lite).html?layout=sdscorso\">Tecnico di&nbsp; IV Livello&nbsp; Europeo</a> Daniele Cappelletti .&nbsp; &nbsp;Erano&nbsp; inoltre&nbsp; presenti&nbsp; ; Alessandro Colombo in rappresentanza degli sport paralimpici e Cristian Dorigatti&nbsp; Tecnico <a href=\"https://www.federclimb.it/\">Fasi</a> in rappresentanza dell&#39;arrampicata sportiva.<br />\r\nDaniele Cappeleltti&nbsp; ha spiegato l&#39;importanza dell&#39;attivit&agrave; fisica sia in et&agrave; giovanile che in et&agrave; adulta, i valori che insegna e trasmette lo sport , proiettando poi alcuni video dello <a href=\"https://www.skyrunningitalia.it/pages/Cos-e-lo-Skyrunning\">skyrunning</a> che hanno molto incuriosito i partecipanti.<br />\r\nL&#39;incontro &egrave; stato anche un&#39;ottima opportunit&agrave; di confronto e scambio di esperienze con i referenti delle altre discipline.&nbsp;&nbsp;<br />\r\n<br />\r\n<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/DANIELE_CAPPELLETTI_c.jpg\" style=\"width: 680px; height: 740px;\" />', 'Daniele Cappelletti - Tecnico di  4Â° livello Europeo - all\'Istituto Agrario di San Michele all\'Adige', 'https://www.skyrunningitalia.it/files/images/DANIELE_CAPPELLETTI_FISKY(1).jpg', '', NULL, 0, 0, '2024-05-29 16:50:08', '2024-05-29 16:50:08', NULL, 1),
(209, 'Skyrunning  Italia:  formazione, informazione e  cultura  ', 'Sabato 25 Maggio&nbsp; si&nbsp; &egrave;&nbsp; tenuto&nbsp; presso&nbsp; il&nbsp; <a href=\"https://www.caibergamo.it/palestra-arrampicata\">Palamonti </a>, sede&nbsp; del&nbsp; <a href=\"https://www.caibergamo.it/\">CAI&nbsp; Bergamo</a>,&nbsp; il&nbsp; Corso&nbsp; di&nbsp; formazione&nbsp; &nbsp;per&nbsp; <a href=\"https://www.skyrunningitalia.it/pages/Formazione-Direttori-di-Gara\">Direttori&nbsp; di&nbsp; Gara&nbsp;</a> promosso&nbsp; dalla&nbsp; FISKY - Federazione&nbsp; Italiana&nbsp; Skyrunning .&nbsp; &nbsp;Il&nbsp; corso&nbsp; &nbsp;ha&nbsp; fornito&nbsp; informazioni&nbsp; a&nbsp; livello&nbsp; organizzativo,&nbsp; di&nbsp; responsabilit&agrave;&nbsp; legali&nbsp; con&nbsp; relazioni&nbsp; ed&nbsp; esempi&nbsp; pratici&nbsp; a&nbsp; coloro&nbsp; che&nbsp; sono&nbsp; coinvolti&nbsp; in&nbsp; prima&nbsp; persona&nbsp; a&nbsp; livello&nbsp; organizzativo&nbsp; nelle&nbsp; competizioni&nbsp; &nbsp;skyrunning.&nbsp; &nbsp;E&#39;&nbsp; stata&nbsp; inoltre&nbsp; presentata&nbsp; un&#39;importante&nbsp; relazione&nbsp; con&nbsp; dati&nbsp; statistici, sull&#39;importante&nbsp; comunicazione&nbsp; realizzata&nbsp; dalla&nbsp; <a href=\"https://www.skyrunningitalia.it/\">FISKY - Federazione&nbsp; Italiana&nbsp; Skyrunning</a>&nbsp;.<br />\r\n<br />\r\n<br />\r\n<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/FISKY_CAI_BERGAMO.jpg\" style=\"width: 700px; height: 444px;\" />', 'Concluso al Palamonti di  Bergamo  il  corso  per  Direttori  di  Gara Skyrunning', 'https://www.skyrunningitalia.it/files/images/DIRETTORI_GARA_FISKY.jpg', '', NULL, 0, 0, '2024-05-29 18:25:21', '2024-05-29 18:55:04', NULL, 1),
(210, 'Raduno  della  Nazionale Skyrunning a  Vezza d\'Oglio', 'Venerd&igrave; 31 maggio, il&nbsp; 1&deg; e il&nbsp; 2&nbsp; giugno la&nbsp; Nazionale&nbsp; Italiana&nbsp; ha&nbsp; &nbsp;fatto&nbsp; tappa a&nbsp; <a href=\"https://www.vezzadoglioturismo.it/\">Vezza d&#39;Oglio (BS) </a>,&nbsp; sui&nbsp; sentieri&nbsp; dell&#39; <a href=\"https://www.adamelloultratrail.it/adamello-series/adamello-vertical-kilometer/\">Adamello Vertical</a>&nbsp; &nbsp;per&nbsp; gli&nbsp; ultimi&nbsp; test&nbsp; che&nbsp; hanno&nbsp; definito&nbsp; gli&nbsp; skyrunner&nbsp; che&nbsp; parteciperanno,&nbsp; il&nbsp; prossimo&nbsp; 28-29-30&nbsp; Giugno,&nbsp; &nbsp;ai&nbsp; <a href=\"https://www.skyrunning-serbia.com/en/kalendar-2024/rumija-skyrunning-28-30-jun-2024/\">Campionati&nbsp; Mondiali&nbsp; Youth&nbsp; &nbsp;a&nbsp; Bar&nbsp; in&nbsp; Montenegro</a><br />\r\nGrande&nbsp; impegno&nbsp; e&nbsp; partecipazione&nbsp; dei&nbsp; giovani&nbsp; &quot;corridori del&nbsp; cielo&quot;&nbsp; &nbsp; che&nbsp; hanno&nbsp; sostenuto&nbsp; test&nbsp; incrementali&nbsp; in&nbsp; palestra,&nbsp; &nbsp;in&nbsp; circuito e&nbsp; seguito&nbsp; lezioni di&nbsp; &nbsp; tecnica&nbsp; di corsa. Un&nbsp; particolare&nbsp; ringraziamento&nbsp; alla&nbsp; ADAMELLO&nbsp; ULTRA TRAIL&nbsp; A.S.D.&nbsp; &nbsp;e&nbsp; alla&nbsp; Palestra&nbsp; <a href=\"https://www.facebook.com/settimocielomalonno/?locale=it_IT\">SETTIMO&nbsp; CIELO&nbsp; di&nbsp; Malonno.</a><br />\r\nQuesta la&nbsp; lista&nbsp; dei&nbsp; convocati :<br />\r\n<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/CONVOCAZIONE-Campionati-YOUTH-2024.jpg\" style=\"width: 654px; height: 925px;\" />', 'Selezione per  i  Campionati  Mondiali Youth -  Lista dei  convocati', 'https://www.skyrunningitalia.it/files/images/FISKY_VEZZA_D_0GLIO.jpg', '', NULL, 0, 0, '2024-06-07 15:31:19', '2024-06-07 15:49:00', NULL, 1),
(211, 'Gli atleti della Nazionale  Italiana Skyrunning al  CeRisM   di  Rovereto', '<br />\r\nLa <a href=\"https://www.skyrunningitalia.it/\">FISky - Federazione Italiana Skyrunning</a> ha iniziato un importante rapporto di collaborazione con il <a href=\"https://www.dnbm.univr.it/?ent=bibliocr&amp;id=285&amp;tipobc=6\">CeRiSM - Centro di Ricerca &ldquo;Sport, Montagna e Salute</a>&rdquo; di Rovereto per consentire ai propri atleti la partecipazione ad una serie di test in ambiente normossico e ipossico , tipico degli ambienti di alta quota teatro delle competizioni skyrunning. Un importante percorso di ricerca per portare gli atleti nazionali nella migliore condizione ai prossimi <a href=\"https://desafiourbion.com/\">Mondiali di settembre in Spagna<br />\r\n<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/fisky_a.jpg\" style=\"width: 600px; height: 450px;\" /></a><br />\r\n<br />\r\nTre giorni di test al Centro Ricerche &ldquo;Sport, Montagna e Salute&rdquo; - CeRiSM&nbsp; con<br />\r\nprotocolli innovativi per la ricerca scientifica nelle metodologie di allenamento per la disciplina skyrunning che la FISky mette a disposizione dei propri atleti Nazionali<br />\r\n<br />\r\nBase&nbsp; per&nbsp; il&nbsp; ritiro&nbsp; della&nbsp; Nazionale&nbsp; il&nbsp; <a href=\"https://www.montedimezzocorona.it/\">Monte&nbsp; di&nbsp; Mezzocorona&nbsp;</a>&nbsp; &nbsp;con&nbsp; il&nbsp; paesaggio&nbsp; della&nbsp; Piana&nbsp; Rotaliana&nbsp; dallo&nbsp; <a href=\"https://www.montedimezzocorona.it/attrazioni-adrenaliniche/\">Sky walk&nbsp; e&nbsp; dal&nbsp; ponte&nbsp; sopseso<br />\r\n<br />\r\n<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/FISKY_Mezzocorona(3).jpg\" style=\"width: 600px; height: 450px;\" /></a>', 'Test  con  protocolli innovativi  e  ritiro  a  Mezzocorona ', 'https://www.skyrunningitalia.it/files/images/Fisky_Cerism_a.jpg', '', NULL, 0, 0, '2024-06-24 18:47:19', '2024-06-24 18:48:41', NULL, 1),
(212, 'Concluso il Corso per  Istruttori Skyrunning  di  2Â° livello   2024', 'Nel&nbsp; weekend del 22 e 23 Giugno,&nbsp; si&nbsp; &egrave;&nbsp; concluso&nbsp; con&nbsp; le&nbsp; prove&nbsp; pratiche&nbsp; e&nbsp; la verifica&nbsp; finale&nbsp; il&nbsp; Corso&nbsp; per Istruttori Skyrunning di&nbsp; 2&deg; livello .&nbsp; Dieci&nbsp; i&nbsp; partecipanti&nbsp; &nbsp; provenienti&nbsp; da&nbsp; Valle d&#39;Aosta, Piemonte, Lombardia, Lazio,&nbsp; Emilia e&nbsp; Sardegna&nbsp; e&nbsp; fra&nbsp; questi&nbsp; &nbsp; tre&nbsp; laureati&nbsp; in&nbsp; scienze&nbsp; motorie&nbsp; che&nbsp; hanno&nbsp; espresso&nbsp; soddisfazione&nbsp; per&nbsp; i&nbsp; contenuti&nbsp; e&nbsp; la&nbsp; professionalit&agrave;&nbsp; nella&nbsp; gestione&nbsp; dei&nbsp; corsi.<br />\r\n<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/FISKY_Corso_Istruttori_2_liv_2024_(2).jpg\" style=\"width: 480px; height: 640px;\" /><br />\r\n&nbsp;', 'Presso la  Sede  S.I.T.  di  Vezzano sul Crostolo (RE)', 'https://www.skyrunningitalia.it/files/images/CORSO_2_LIVELLO_2024.jpg', '', NULL, 0, 0, '2024-06-25 12:06:00', '2024-06-27 21:49:04', NULL, 1),
(213, 'Conclusi a Bar (Montenegro) i Campionati del Mondo Youth 2024', 'Ottimo debutto il 28 Giugno ai Mondiali Skyrunning Youth in Montenegro. Nel Vertical di 5,5 km con D 1.000 mt arrivano subito una medaglia d&rsquo;oro <img alt=\"ðŸ¥‡\" height=\"16\" referrerpolicy=\"origin-when-cross-origin\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t94/1/16/1f947.png\" width=\"16\" /> ,una d&rsquo;argento <img alt=\"ðŸ¥ˆ\" height=\"16\" referrerpolicy=\"origin-when-cross-origin\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t15/1/16/1f948.png\" width=\"16\" /> e tanti ottimi piazzamenti:<br />\r\n1&rsquo; - Marco Magistro - Youth A<br />\r\n2&rsquo; - Alex Rigo - U 23<br />\r\n4&rsquo; - Davide Songini - Youth A<br />\r\n4&rsquo; - Peter Bettoli - Youth C<br />\r\n5&rsquo; - Alessandro Rossi - U 23<br />\r\n10&rsquo; - Antonio Corti - Youth C<br />\r\n11&rsquo; - Simone Dalle - Youth C<br />\r\n15&rsquo; - Davide Gadin - Youth B<br />\r\n16&rsquo; - Enrico Rota Martir - U 23<br />\r\n23&rsquo; - Maurizio Bonfante - Youth B<br />\r\n24 - Joseph Philippot - U 23<br />\r\n30 - Riccardo Matergia- Youth C<br />\r\n<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/FISKY_Marco_Magistro.jpg\" style=\"width: 250px; height: 189px;\" /><img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/FISKY_ALEX_RIGO.jpg\" style=\"width: 250px; height: 188px;\" /><br />\r\nNella&nbsp; prova&nbsp; conclusiva&nbsp; di&nbsp; domenica&nbsp; &nbsp;dove&nbsp; le&nbsp; categorie&nbsp; Youth A e B si&nbsp; sono&nbsp; cimentate&nbsp; &nbsp;du&nbsp; un&nbsp; impegnativo&nbsp; percorso&nbsp; di&nbsp; 12 km D+ 800 m.&nbsp; e&nbsp; le&nbsp; categorie Youth C e U23 sulla Skyrace di 21 km con D+ 1.600 m.&nbsp; ottima&nbsp; prestazione&nbsp; del&nbsp;nostro Peter Bettoli, che dopo la medaglia di legno del 4&deg; posto nella prova Vertical di venerd&igrave; si &egrave; aggiudicato oggi due medaglie di bronzo : la prima nella Skyrace dietro l&#39;imprendibile tedesco Lukas Ehrle e allo spagnolo Llu&igrave;s Puigvert Palacios e davanti all&#39;altro spagnolo Iu Net Puig.<br />\r\nGrazie a questi piazzamenti la seconda medaglia di bronzo &egrave; arrivata con le stesse posizioni di classifica nella Combinata ( Vertical + Sky ).<br />\r\nDa rimarcare l&#39;ottima prestazione dell&#39;unica rappresentante italiana in campo femminile, Elisa Mariani che ha ottenuto un buon 12&deg; posto nella categoria Youth B.<br />\r\nQuesti i piazzamenti degli altri italiani in gara:<br />\r\n12&deg; - Matteo Mariani (Youth A)<br />\r\n14&deg; - Riccardo Chiolerio (Youth B )<br />\r\n14&deg; - Joseph Philippot (U 23)<br />\r\n16&deg; - Lorenzo Fontana (Youth A )<br />\r\n16&deg; - Simone Dalle (Youth C )<br />\r\n17&deg; - Davide Gadin ( Youth B )<br />\r\n17&deg; - Enrico Rota Martir (U 23)<br />\r\n29&deg; - Riccardo Matergia (Youth C )<br />\r\nRit. - Alessandro Rossi ( U23 )<br />\r\nRit. - Antonio Corti Youth C )<br />\r\nQuattro le medaglie vinte:<br />\r\n<img alt=\"ðŸ¥‡\" height=\"16\" referrerpolicy=\"origin-when-cross-origin\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t94/1/16/1f947.png\" width=\"16\" />- Marco Magistro -<br />\r\n<img alt=\"ðŸ¥ˆ\" height=\"16\" referrerpolicy=\"origin-when-cross-origin\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t15/1/16/1f948.png\" width=\"16\" />- Alex Rigo<br />\r\n<img alt=\"ðŸ¥‰\" height=\"16\" referrerpolicy=\"origin-when-cross-origin\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t96/1/16/1f949.png\" width=\"16\" /><img alt=\"ðŸ¥‰\" height=\"16\" referrerpolicy=\"origin-when-cross-origin\" src=\"https://static.xx.fbcdn.net/images/emoji.php/v9/t96/1/16/1f949.png\" width=\"16\" />- Peter Bettoli<br />\r\n<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/FISKY_Peter_Bettoli_combinata.jpg\" style=\"width: 550px; height: 437px;\" /><br />\r\nNella classifica per Nazioni l&#39;Italia chiude al 6&deg; posto sulle 28 Nazioni presenti , scontando la mancanza di atlete in campo femminile , dietro a Spagna, Giappone, Regno Unito, Repubblica Ceca e Norvegia.<br />\r\nUn risultato pi&ugrave; che positivo che ha fornito importanti indicazioni per la crescita del movimento giovanile nel quale la <a href=\"https://www.skyrunningitalia.it/\">FISky - Federazione Italiana Skyrunning </a>sta investendo e lavorando col massimo impegno.', 'Ottima  prestazione  collettiva  con  acuti  di  Magistro, Rigo e Bettoli', 'https://www.skyrunningitalia.it/files/images/FISKY_Team_Youth.jpg', '', NULL, 0, 0, '2024-07-01 10:05:21', '2024-07-01 10:08:51', NULL, 1),
(214, 'Campionati Italiani SkyMarathon 2024 ', 'In occasione della <a href=\"https://www.monterosaww.com/\">Monte Rosa Walserwaeg</a> disputata nel weekend del 6-7 luglio, l&rsquo;alta Valle del Lys ha ospitato la prova SkyMarathon valevole come <a href=\"https://www.skyrunningitalia.it/pages/Campionati-Italiani-2024\">Campionato Italiano FISky</a> assoluto e di categoria per la specialit&agrave;; corona d&rsquo;alloro per <strong>Cristian</strong> <strong>Minoggio</strong> e <strong>Roberta Jacquin</strong> che sugli antichi sentieri walser si sono aggiudicati il titolo tricolore; nella prova&nbsp; Trail da 9 km corsa domenica 7 luglio, la vittoria della quarta tappa di <a href=\"https://www.skyrunningitalia.it/pages/COPPA-ITALIA-Giovani-2024-Supported-by-LOACKER\">Coppa Italia Giovani by Loacker </a>&egrave; andata a <strong>Riccardo Chiolerio</strong> ed <strong>Elisa Mariani.</strong><br />\r\n<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/Monterosa_W_45_PH_Stefano_Jeantet-7.jpg\" style=\"width: 500px; height: 333px;\" /><br />\r\nLa prova Marathon della gara valdostana, organizzata da <strong>Outdoor With Us</strong> sotto la supervisione del pluricampione Franco Coll&egrave;, ha visto il trionfo degli atleti azzurri <strong>Cristian Minoggio</strong> e <strong>Roberta Jacquin </strong>che nella gara da 45 km, valevole come prova unica di Campionato Italiano, si sono aggiudicati il tricolore 2024 battendo la concorrenza su un tracciato impegnativo quanto spettacolare sui sentieri d&rsquo;alta quota della Vall&eacute;e.<br />\r\n&nbsp;\r\n<p dir=\"ltr\">A spuntarla sui compagni di casacca azzurra sul traguardo di Gressoney &egrave; stato&nbsp;<strong> il campione del Mondo Cristian Minoggio (Altitude Skyrunning Team ASD)</strong> che con il tempo di 4h38&rsquo;37&rdquo; si &egrave; aggiudicato titolo e gara, lasciandosi alle spalle <strong>Gianluca Ghiano</strong> (4h39&rsquo;45&rdquo; - <strong>ASD Santiano Dante)</strong> e <strong>Mattia Tanara </strong>(4h48&rsquo;16&rdquo; - <strong>ASD Km Sport</strong>), che confermano le aspettative della vigilia completando un podio di spessore.</p>\r\n\r\n<p dir=\"ltr\">Al femminile la valdostana <strong>Roberta Jacquin (ASD Peragun)</strong> regola la concorrenza trionfando in 6h02&rsquo;05&rdquo; davanti all&rsquo;atleta di casa <strong>Marina Cugnetto (ASD Outdoor With Us</strong>) che ha fermato il cronometro a 6h24&rsquo;57&rdquo;. Terzo gradino del podio tricolore per<strong> Federica Spadafora (APD Pont Saint Martin)</strong> che ha chiuso in 7h26&rsquo;57&rdquo;.</p>\r\n', 'CRISTIAN MINOGGIO E ROBERTA JACQUIN SI LAUREANO CAMPIONI ITALIANI SKYMARATHON 2024', 'https://www.skyrunningitalia.it/files/images/FISKY_CAMP_SKYMARATHON_2024.jpg', '', NULL, 0, 0, '2024-07-10 10:59:59', '2024-07-10 10:59:59', NULL, 1),
(215, 'Raduno  della  Nazionale Skyrunning  a  Gressoney-Saint-Jean ', '(Gressoney-Saint-Jean 6-12 Luglio) - In&nbsp; occasione&nbsp; del&nbsp; <a href=\"https://www.monterosaww.com/\">Monterosa&nbsp; Walse Waeg</a>&nbsp; gara che&nbsp; sulla&nbsp; distanza&nbsp; di&nbsp; 43&nbsp; km km&nbsp; D+ 3.170 m.&nbsp; assegnava&nbsp; i&nbsp; Titoli&nbsp; Italiani&nbsp; Assoluti e di Categoria&nbsp; nella&nbsp; specialit&agrave;&nbsp; SkyMarathon ,&nbsp; si&nbsp; &egrave;&nbsp; tenuto il quarto raduno stagionale della Nazionale Italiana Skyrunning sui sentieri Walser di <a href=\"https://www.lovevda.it/it/banca-dati/3/localita/valle-d-aosta/gressoney-saint-jean/392\">Gressoney-Saint-Jean </a>in preparazione dei prossimi<a href=\"https://desafiourbion.com/\"> Mondiali di Settembre in Spagna</a>. Un particolare ringraziamento al <a href=\"https://www.comune.gressoneystjean.ao.it/it-it/home\">Comune di Gressoney-Saint-Jean</a>, all&#39;Hotel Lyshaus e al Ristorante &quot;Lo Stambecco&quot; per l&#39;ospitalit&agrave; e la collaborazione riservataci&nbsp; (sotto&nbsp; gli&nbsp; atleti&nbsp; ai piedi&nbsp; del&nbsp; Monte&nbsp; Rosa)<br />\r\n<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/FISKY_RADUNO_GRESSONEY_SAINT_JEAN.jpg\" style=\"width: 550px; height: 451px;\" /><br />\r\n<br />\r\nDopo&nbsp; aver&nbsp; partecipato&nbsp; alla&nbsp; prova&nbsp; di&nbsp; 43 km&nbsp; &nbsp;con&nbsp; D+ 3.170 m.&nbsp; le&nbsp; atlete&nbsp; e&nbsp; gli&nbsp; atleti&nbsp; della&nbsp; Nazionale si sono dedicati&nbsp; alla&nbsp; preparazione&nbsp; con&nbsp; test&nbsp; presso&nbsp; la&nbsp; Gressoney Sport&nbsp; Haus&nbsp;<br />\r\n<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/FISKY_test_4.jpg\" style=\"width: 550px; height: 413px;\" /><br />\r\n<br />\r\nproseguendo&nbsp; poi&nbsp; con&nbsp; allenamti&nbsp; in&nbsp; quota&nbsp; sino&nbsp; al&nbsp; Rifugio&nbsp; Quintino&nbsp; Sella&nbsp; &nbsp;con&nbsp; la&nbsp; partecipazione e&nbsp; la&nbsp; collaborazione&nbsp; di&nbsp; <strong>Franco&nbsp; Coll&egrave;&nbsp;</strong> <strong><em>deus ex machina&nbsp;&nbsp;</em></strong>della&nbsp; manifestazione&nbsp; che&nbsp; anche&nbsp; quest&#39;anno&nbsp; ha&nbsp; fatto&nbsp; registrare&nbsp; il&nbsp; sold-out&nbsp; di partecipanti<br />\r\n<br />\r\n<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/FISKY_SELLA.jpg\" style=\"width: 600px; height: 800px;\" />', 'In  preparazione  dei  prossimi  Mondiali  di  Settembre  in  Spagna', 'https://www.skyrunningitalia.it/files/images/FISKY_RIFUGIO_Q_SELLA.jpg', '', NULL, 0, 0, '2024-07-10 11:51:51', '2024-07-10 11:57:10', NULL, 1);
INSERT INTO `news` (`id`, `title`, `text`, `description`, `image`, `author`, `header_image`, `keep_header`, `not_header`, `created`, `modified`, `subtitle`, `status`) VALUES
(216, 'Cristian Minoggio e Daniela Rota si laureano campioni italiani Ultra SkyMarathon  alla MUST', '<strong>Cristian&nbsp; Minoggio raddoppia e al femminile la nuova campionessa italiana &egrave; la bergamasca Daniela Rota. Il piemontese, neo campione italiano sulla distanza marathon, ora &egrave; anche campione italiano ultra skymarathon (Fisky) e nuovi record di percorso maschile e femminile.</strong><br />\r\n<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/MINOGGIO3-2048x1365.jpeg\" style=\"width: 600px; height: 400px;\" /><br />\r\nAbbassando di circa 20 minuti il tempo stampato dal bergamasco Luca Arrigoni lo scorso anno, il nuovo campione italiano ultra skymarathon Cristian Minoggio ha messo la sua firma anche sul nuovo tempo da battere. Cinque ore, 12 minuti e 21 secondi per l&rsquo;atleta del team Kailas che, sui sentieri della <a href=\"https://www.valdiscalve.it/\">Val di Scalve</a>, ha sottolineato per la seconda volta in un paio di settimane di essere il pi&ugrave; veloce. Prima conquistando il titolo tricolore sulla marathon (ottenuto alla Monte Rosa WalserWaeg che si &egrave; svolta il primo fine settimana di luglio in quel di <a href=\"https://www.comune.gressoneystjean.ao.it/it-it/home\">Gressoney</a>) e ora qui, nella tecnica e impegnativa MUST sul percorso lungo da 47 km e 3600 D+, prova unica <a href=\"https://www.skyrunningitalia.it/pages/Campionati-Italiani-2024\">Campionato italiano Ultra Skymarathon Fisky.</a><br />\r\n<br />\r\nAnche nel 2022,&nbsp;<strong>Cristian Minoggio</strong>&nbsp;si era laureato campione lasciandosi dietro&nbsp;<strong>Luca Arrigoni</strong>&nbsp;che, anche questa volta, &egrave; secondo con il tempo di 05:41:52. Gara non priva di colpi di scena. &Egrave; stata lotta e sprint al fotofinish per Mauro Rota, Luca Carrara e Giulio Ornati nel tentativo di portarsi a casa il terzo gradino del podio. E sebbene nel cuore degli spettatori i tre sono terzi a pari merito, il timer &egrave; impietoso: terzo posto per&nbsp;<strong>Mauro Rota</strong>&nbsp;(06:12:02), quarto per&nbsp;<strong>Luca Carrara</strong>&nbsp;(06:12:03: 182) e quinto per&nbsp;<strong>Giulio Ornati</strong>&nbsp;(06:12:03:549).<br />\r\n<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/ROTA-700x467.jpeg\" style=\"width: 600px; height: 400px;\" />\r\n<p>Tra le donne trionfo di<strong>&nbsp;Daniela Rota</strong>&nbsp;(team Fly Up Sport &ndash; Scott) come da pronostico. La bergamasca ha staccato la seconda classificata&nbsp;<strong>Elisa Pallini</strong>&nbsp;di una ventina di minuti e la terza classificata,<strong>&nbsp;Milena Pasin</strong>, di oltre un&rsquo;ora. Anche per lei, cos&igrave; come per il &ldquo;collega&rdquo; Minoggio, nuovo record di percorso. Al femminile il nuovo tempo da battere &egrave; da oggi 06:44:23.</p>\r\n\r\n<p>&ldquo;Secondo anno di <a href=\"https://must-ultratrail.it/\">MUST</a> e secondo successo stellare. MUST si conferma una gara sentita e partecipata, che ha davanti a s&eacute; un futuro ricco di riconoscimenti e soddisfazioni. Sono davvero felice di aver avuto sui sentieri scalvini un campione della caratura di Minoggio, che d&agrave; lustro alla gara e al territorio. I complimenti vanno anche alla bergamasca e team Scott Daniela Rota, che quest&rsquo;anno sta volando davvero alto. Grazie al vicesindaco di <a href=\"https://www.comune.colere.bg.it/\">Colere </a>Leandro Belingheri, ideatore della gara, e a tutti gli enti e i volontari che con passione e impegno l&rsquo;hanno resa possibile. E anche alla FISky, per aver puntato sulla nostra gara per assegnare il prestigioso titolo tricolore. Lunga vita alla <a href=\"https://must-ultratrail.it/\">MUST</a>&rdquo;. (<strong>Mario Poletti</strong>, Fly Up Sport)</p>\r\n<br />\r\n&nbsp;', 'Quasi 400 al via della Memorial Ultra Scalve Trail 2024 ', 'https://www.skyrunningitalia.it/files/images/FISKY__MUST_2024.jpg', '', NULL, 0, 0, '2024-07-23 17:14:36', '2024-07-23 17:14:44', NULL, 1),
(217, 'Ecco  i  nomi  dei  convocati  per  i prossimi Campionati Mondiali Skyrunning', 'Ufficializzata la lista della Nazionale che rappresenter&agrave; l&#39;Italia ai prossimi <a href=\"https://desafiourbion.com/\">Campionati Mondiali Skyrunning</a> in Spagna il 6-7-8 Settembre 2024. L&#39;obiettivo &egrave; difendere il <a href=\"https://www.skyrunningitalia.it/pages/Calendario-Gare-2024\">Titolo Mondiale</a> conquistato in Val d&#39;Ossola nel 2022.<br />\r\n<br />\r\n<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/CONVOCAZIONE-Campionati-Mondiali-2024.jpeg\" style=\"width: 700px; height: 990px;\" />', 'Dal  6  all\' 8  Settembre  a  Soria  (Spagna)', 'https://www.skyrunningitalia.it/files/images/FISKY_Mezzocorona(1).jpg', '', NULL, 0, 0, '2024-08-06 18:53:27', '2024-08-06 19:02:34', NULL, 1),
(218, 'Prosegue il  progetto  di  ricerca  CERISM  -  FISKY', '<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/FISKY_Skywalk_Monte_Mezzocorona.jpg\" style=\"width: 640px; height: 480px;\" /><br />\r\n27-28-29 Agosto - Il progetto di collaborazione tra <a attributionsrc=\"/privacy_sandbox/comet/register/source/?xt=AZULXlaoPLEvRl1USVFOhtGB4VwKkd2Nnw1s2uYWxv_H2BOnCla5o4jJS_Ka7_r5d9BrjUeoGtT5BWPnI9Ehi_c_Ay0AQ6mBvhw6nmUsbdIJ94U3FD9fUn4oI9Gu42oGcX0Q5W_lYUL8FB4CB1IYt9YEtobKAdqauo8eKt7Ak8pPKnmYGIqu5lAPpbJfBNPEyytRhEGaMt1gbiiLuHSh0vTxQli8qUwcyPliWU-cQg6Qf3k7AbdF2NgEVEKji9Y8uGIaynvlZRJlIJc-5T3MH49dTmq8Fabpox5gHPqxA9jOBewLmZaaXmHrWP5b54NoE27e9k03VXbbGy0MACGLFRf3jmH56PMnhi1SWoizM2mE3hkiID2dFa0LiDzM7rEWP4Vi45sdnBjjGl-uKkZJa2d13lGiO9XXWrxr_JFJwm5Xw1IowbL5ljyE8Y_u9dfCyZW7i8SpUuTovfJc1V-1VLI94LIqLsfoYwDN6CdasqX1CRGG_z85Vzu5DD7W1V2NabO_LS0MwoOHaAJHFk16nwyaoRhnUKYzB_iNUPhEvF8_0597JhSQ2De0Fb0SDcVIl4HVGoehH2SQ0FvQn182wGIzfj2XVbZYQRuJ2_Hx0nJ53yMms5muCl8GaBYAuj0LS8g_gh-MowRJGxKI2dNqyCSo5wP0uWCe8ZFks86sptGUrxQdZV_olFg7L4d4jX6NaESLHKxn5slJFCK00aecbTqSSAaa_klwvt7FkWG1rOnIodiQtpn9VN3-awmEoz9oYIyExvCWEt-0tBBbpSjcutQQ7qxEiJDMyQzWkzyJRzci2cMe4rCqkHwIY6MbtppqwMOKZmqivnyc6ExKFFB5cNMagEcnOcFmSyy1fUvCDqRV9r3ja437oUKwBNDYRIkkwPPSOAkTHFZQk9Q5kLCTTRgmn_ElkFXMJCapRQyzIi104zyhx5bFlgfzZdkXqx3MDX4msOkE3W2-2Z42hNPZkzlnjtbJ89JJtpwZ0I-6JSyQlUAMVKnB-GEHGDbWgAyXkhFLvlMOHBN44Sodc4YjQ_PUiBhsXgT1DugxxeCOucsMjJNfX3IQ_ardXmzHBt9-H1VV5UrP5IViZ9daeNQkGbrzS0bLwDrRCS5DHvq6x7hP1gKsusYJHs-mpVQAuGIeJODw2xO8m6mcQaLEsfCrhf4IGeAuOYJ2pFA2QFrnxUxL0UzSIo1J2s9UjgROSJTXz2EhA5l_nNvBMGvTZwww9QfYz76T4xZ9P8ANYNpmfa6jBs0P5So1KMG1euMH8Ev52VgrDyb2tYmgFYtrOBxdRw6ngcE1QWS-HKRdELWgI-dsDD4j6M_B2rpNk3Y7D2Wh1_d0BVlSlj1FJk5MWDIGfEVJffZFV58-moKJWbq-6XWQzvYlkra3DTO7fHGLpD6OGQkSjrgAXm8_2woFQ-43juYYOwYLujcbApYl4mlubWr3oV9NJ4m7BMBEOpR7HT8Pzdw\" href=\"https://www.facebook.com/skyrunning2023?__cft__[0]=AZU3ixT1aheSI2RlQseCaHJm0s6GfBGXUGs9iPM602EVNfvXvNbpMpM1m3VnSu9O9JdQ3vr3FKJth2_9NIxSgtxuugcoIpltFgEoEx3H8QkuMO1QpPGZOJLNV0wYB-r45YuU