INSERT INTO `webpages` (`id`, `title`, `text`, `status`) VALUES
(73, 'Ranking FISky Skyrunning 2022', '<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/FISKY_Mezzocorona.jpg\" style=\"width: 700px; height: 429px;\" />\r\n<h2>&nbsp;</h2>\r\n\r\n<h3><strong><a href=\"https://www.skyrunningitalia.it/files/files/Categorie_FISKY_maschili_2022.pdf\">CATEGORIE&nbsp; FISky&nbsp; -&nbsp; Maschili&nbsp; -&nbsp; aggiornato&nbsp; al&nbsp; 31 Dicembre 2022</a></strong></h3>\r\n&nbsp;\r\n\r\n<h3><strong><a href=\"https://www.skyrunningitalia.it/files/files/Categorie_FISKY_femminili_2022.pdf\">CATEGORIE&nbsp; FISky&nbsp; -&nbsp; Femminili -&nbsp; aggiornato&nbsp; al 31 Dicembre 2022</a></strong></h3>\r\n\r\n<div style=\"text-align: justify;\"><br />\r\nIl Ranking FISky Skyrunning 2022 &egrave;&nbsp; calcolato in&nbsp; base ai risultati ottenuti&nbsp; nelle&nbsp; gare&nbsp; del&nbsp; calendario ufficiale&nbsp; FISky.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Le Categorie sono assegnate&nbsp; in base alla differenza percentuale del tempo ottenuto rispetto al record della gara.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; E&#39; considerato record della gara il minor tempo assoluto ottenuto da atleta italiano/a&nbsp; /F e M)<br />\r\nPrima categoria FISky : entro il 112,5% del record della gara&nbsp; (F e M )<br />\r\nSeconda categoria FISky : entro il 125,0% del record della gara&nbsp; (F e M )<br />\r\nTerza categoria FISky ; entro il 137,5% del record della&nbsp; gara (F e M)<br />\r\nQuarta&nbsp; categoria&nbsp; FISky : entro il&nbsp; 150,0% del record della gara (F e M )<br />\r\nGli&nbsp; atleti / e con tempi&nbsp; oltre&nbsp; il 150% del record della gara&nbsp; sono&nbsp; considerati &quot;Non Classificati&quot;<br />\r\nNota: la partecipazione di atleti di alto livello, anche &quot;Non Classificati&quot; che&nbsp; miglioreranno i record delle gare selezionate per&nbsp; l&#39;anno in corso, innalzer&agrave; progressivamente il livello delle&nbsp; singole categorie.<br />\r\nNota: obiettivo dell&#39;assegnazione delle Categorie FISky &egrave; l&#39;innalzamento del livello tecnico dello Skyrunning in Italia.<br />\r\nNota: in caso di assegnazione di categorie diverse per&nbsp; una&nbsp; stessa tipologia di gara, vale il risultato migliore.<br />\r\nNota: eventuali errori o omissioni possono essere&nbsp; segnalati&nbsp; alla&nbsp; FISky alla&nbsp; mail :&nbsp;&nbsp;<a href=\"mailto:federazione@skyrunningitalia.it\">federazione@skyrunningitalia.it</a>&nbsp;</div>\r\n', 1);
INSERT INTO `webpages` (`id`, `title`, `text`, `status`) VALUES
