(81, 'Classifica e Montepremi per SocietÃ ', '<h2 style=\"text-align: center;\"><img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/REGOLAMENTO_2025__CLASSIFICA__SKYRUNNING__PER__SOCIETA_page-0001.jpg\" style=\"width: 741px; height: 1048px;\" /><br />\r\n<span style=\"color:#e74c3c;\"><strong>&nbsp;<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/CLASSIFICA_PER_SOCIETA_2025_page-0001.jpg\" style=\"width: 900px; height: 1273px;\" /><br />\r\n<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/CLASSIFICA_PER_SOCIETA_2025_page-0002.jpg\" style=\"width: 900px; height: 1273px;\" /><br />\r\n<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/CLASSIFICA_PER_SOCIETA_2025_page-0003.jpg\" style=\"width: 900px; height: 1273px;\" /><br />\r\n<br />\r\n<br />\r\n<br />\r\nCLASSIFICA&nbsp; SKYRUNNING&nbsp; PER&nbsp; SOCIETA&#39;&nbsp; 2024<br />\r\n<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/classifica-FINALE-Societa-FISKY-2024-.jpg\" style=\"width: 900px; height: 1866px;\" /><br />\r\n<br />\r\n<br />\r\nCLASSIFICA&nbsp; SKYRUNNING&nbsp; PER&nbsp; SOCIETA&#39;&nbsp; 2023</strong></span></h2>\r\n<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/CLASSIFICA_FINALE_SOCIETA\'_FISKY_2023_00001.jpg\" style=\"width: 700px; height: 990px; float: left;\" /><br />\r\n<img alt=\"\" src=\"https://www.skyrunningitalia.it/files/images/CLASSIFICA_FINALE_SOCIETA\'_FISKY_2023_00002(1).jpg\" style=\"width: 700px; height: 990px; float: left;\" /><br />\r\n&nbsp;', 1),
(84, 'Atlete/i  Nazionale Giovanile 2023', '<!-- INIZIO RIGA -->\r\n<div class=\"row\">\r\n<div class=\"col-xl-4 col-lg-4 col-md-4 col-sm-12 col-12\">\r\n<div class=\"team-block mb30\">\r\n<div class=\"team-img mb30\"><img class=\"img-fluid\" src=\"https://www.skyrunningitalia.it/files/images/Foto_Atleti/Bonacina_Andrea\" /></div>\r\n\r\n<div class=\"team-content text-center\">\r\n<h3>Andrea BONACINA</h3>\r\n<a class=\"open-popup-link\" href=\"#popup-43\"><small class=\"designation\">Palmares</small></a></div>\r\n\r\n<div class=\"white-popup mfp-hide\" id=\"popup-43\">&nbsp;</div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"col-xl-4 col-lg-4 col-md-4 col-sm-12 col-12\">\r\n<div class=\"team-block mb30\">\r\n<div class=\"team-img mb30\"><img class=\"img-fluid\" src=\"https://www.skyrunningitalia.it/files/images/Foto_Atleti/Compagnoni_Luca\" /></div>\r\n\r\n<div class=\"team-content text-center\">\r\n<h3>Luca COMPAGNONI</h3>\r\n<a class=\"open-popup-link\" href=\"#popup-35\"><small class=\"designation\">Palmares</small></a></div>\r\n\r\n<div class=\"white-popup mfp-hide\" id=\"popup-35\">&nbsp;</div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"col-xl-4 col-lg-4 col-md-4 col-sm-12 col-12\">\r\n<div class=\"team-block mb30\">\r\n<div class=\"team-img mb30\"><img class=\"img-fluid\" src=\"https://www.skyrunningitalia.it/files/images/Foto_Atleti/Fioroni_Simone\" /></div>\r\n\r\n<div class=\"team-content text-center\">\r\n<h3>Simone FIORONI</h3>\r\n<a class=\"open-popup-link\" href=\"#popup-56\"><small class=\"designation\">Palmares</small></a></div>\r\n\r\n<div class=\"white-popup mfp-hide\" id=\"popup-56\">&nbsp;</div>\r\n</div>\r\n</div>\r\n</div>\r\n<!-- FINE RIGA --><!-- INIZIO RIGA -->\r\n\r\n<div class=\"row\">\r\n<div class=\"col-xl-4 col-lg-4 col-md-4 col-sm-12 col-12\">\r\n<div class=\"team-block mb30\">\r\n<div class=\"team-img mb30\"><img class=\"img-fluid\" src=\"https://www.skyrunningitalia.it/files/images/Foto_Atleti/Romagnoli_Tommaso\" /></div>\r\n\r\n<div class=\"